const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Santa Monica coast geometry
  const santaMonica = ee.Geometry.Point([-118.4912, 34.0195]);
  const bufferGeom = santaMonica.buffer(10000); // 10km buffer for coastal area

  // Date range around October 10, 2015
  const startDate = '2015-10-05';
  const endDate = '2015-10-15';

  // Load Landsat 8 data
  let col = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterBounds(bufferGeom)
    .filterDate(startDate, endDate)
    .filter(ee.Filter.lt('CLOUD_COVER', 30));

  let size = col.size().getInfo();
  console.log(`Landsat 8 images found (Oct 5-15, 2015): ${size}`);

  // If no Landsat, try Sentinel-2
  if (size === 0) {
    col = ee.ImageCollection('COPERNICUS/S2_SR')
      .filterBounds(bufferGeom)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30));
    size = col.size().getInfo();
    console.log(`Sentinel-2 images found (Oct 5-15, 2015): ${size}`);

    if (size === 0) {
      console.log('No data available for October 10, 2015 near Santa Monica.');
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // Use first available image
  const img = col.first();

  // Calculate Floating Chlorophyll Index (FCI) for algae detection
  // FCI = (NIR - Red) / (NIR + Red)
  const fci = img.normalizedDifference(['B5', 'B4']).rename('FCI');

  // Count valid pixels
  const count = fci.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: bufferGeom,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const validPixels = count.FCI || 0;
  console.log(`Valid FCI pixels after masking: ${validPixels}`);

  if (validPixels === 0) {
    console.log('No valid pixels after cloud masking.');
    console.log('<answer>C2</answer>');
    return;
  }

  // Calculate mean FCI value
  const stats = fci.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: bufferGeom,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const meanFCI = stats.FCI;
  console.log(`Mean FCI value: ${meanFCI !== null ? meanFCI.toFixed(4) : 'null'}`);

  if (meanFCI === null || isNaN(meanFCI)) {
    console.log('FCI calculation resulted in invalid value.');
    console.log('<answer>C3</answer>');
    return;
  }

  // Algae bloom threshold: FCI > 0.15 indicates potential bloom
  const bloomThreshold = 0.15;
  const percentileHigh = fci.reduceRegion({
    reducer: ee.Reducer.percentile([75]),
    geometry: bufferGeom,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const p75 = percentileHigh.FCI || 0;
  console.log(`75th percentile FCI: ${p75.toFixed(4)}`);
  console.log(`Bloom threshold: ${bloomThreshold}`);

  const bloomDetected = meanFCI > bloomThreshold || p75 > bloomThreshold;

  if (bloomDetected) {
    console.log('Algae bloom signature detected off Santa Monica coast.');
    console.log('<answer>A</answer>');
  } else {
    console.log('No significant algae bloom detected.');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
